import {
    STORY_SECTION_HEADINGS,
    STORY_SECTION_KEYS,
    type CreateStoryBody,
    type ProjectStorySummary,
    type SavedStoryDraft,
    type StorySectionKey,
} from '@motivation/shared';
import stylesText from './project-story-list.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { formatProjectStatusLabel, projectStatusClass } from '../project-shared.js';
import { ProjectsService } from '../../../../services/projects.service.js';
import { createComponentLogger } from '../../../../utils/component-logger.js';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
<div class="state" id="loading">Loading stories…</div>
<div class="state" id="error" hidden></div>
<div class="toolbar" hidden id="toolbar">
    <button type="button" id="new-story">+ New story</button>
</div>
<ul class="story-list draft-list" id="drafts" aria-label="Story drafts"></ul>
<ul class="story-list" id="stories"></ul>
<template id="item-template">
    <li class="story-entry">
        <details class="story-item">
            <summary class="item-summary">
                <span class="item-text">
                    <span class="item-id"></span>
                    <span class="item-title"></span>
                </span>
                <span class="status"></span>
            </summary>
            <div class="item-body">
                <p class="item-copy" hidden></p>
                <p class="item-meta"></p>
            </div>
        </details>
    </li>
</template>
<template id="draft-template">
    <li class="story-entry draft-entry">
        <details class="story-item">
            <summary class="item-summary">
                <span class="item-text">
                    <span class="item-id"></span>
                    <span class="item-title"></span>
                </span>
                <span class="status status--draft"></span>
            </summary>
            <div class="item-body">
                <p class="item-copy" hidden></p>
                <p class="item-meta"></p>
                <div class="draft-actions" hidden>
                    <button type="button" class="edit-button">Edit</button>
                    <button type="button" class="discard-button">Discard</button>
                </div>
                <pre class="item-error" hidden></pre>
            </div>
        </details>
    </li>
</template>
<template id="form-template">
    <form class="story-form">
        <label class="field">
            <span class="field-label">Title</span>
            <input type="text" name="title" maxlength="200" required />
        </label>
        <div class="sections"></div>
        <details class="more-fields">
            <summary>More fields</summary>
            <div class="more-sections"></div>
        </details>
        <p class="form-note">Saved as a draft; <code>npm run stories:import</code> at the desktop writes it as a story file.</p>
        <div class="form-actions">
            <button type="submit" class="save-button">Save draft</button>
            <button type="button" class="cancel-button">Cancel</button>
        </div>
        <pre class="form-error" hidden></pre>
    </form>
</template>
<template id="section-template">
    <label class="field">
        <span class="field-label"></span>
        <textarea rows="4"></textarea>
    </label>
</template>
`;

/**
 * Story 465: the stories are read-only here (editing one is a desktop job). A new story is saved as a
 * draft, listed above them until `npm run stories:import` writes it as a story file; a converted draft
 * stays, with its number, until that story reaches the list (the VPS's clone is pulled by hand). Where a
 * story goes on the board is decided at the desktop, not here.
 */
export class ProjectStoryList extends HTMLElement {
    private shadowRootRef: ShadowRoot;
    private loadingEl!: HTMLElement;
    private errorEl!: HTMLElement;
    private toolbarEl!: HTMLElement;
    private draftsEl!: HTMLElement;
    private storiesEl!: HTMLElement;
    private itemTemplateEl!: HTMLTemplateElement;
    private draftTemplateEl!: HTMLTemplateElement;
    private formTemplateEl!: HTMLTemplateElement;
    private sectionTemplateEl!: HTMLTemplateElement;
    private loadSequence = 0;
    private readonly log = createComponentLogger('project-story-list');

    static get observedAttributes(): string[] {
        return ['project-id'];
    }

    constructor() {
        super();
        this.shadowRootRef = this.attachShadow({ mode: 'open' });
        this.shadowRootRef.adoptedStyleSheets = [styles];
        this.shadowRootRef.appendChild(template.content.cloneNode(true));
    }

    connectedCallback(): void {
        this.loadingEl = this.shadowRootRef.getElementById('loading') as HTMLElement;
        this.errorEl = this.shadowRootRef.getElementById('error') as HTMLElement;
        this.toolbarEl = this.shadowRootRef.getElementById('toolbar') as HTMLElement;
        this.draftsEl = this.shadowRootRef.getElementById('drafts') as HTMLElement;
        this.storiesEl = this.shadowRootRef.getElementById('stories') as HTMLElement;
        this.itemTemplateEl = this.shadowRootRef.getElementById('item-template') as HTMLTemplateElement;
        this.draftTemplateEl = this.shadowRootRef.getElementById('draft-template') as HTMLTemplateElement;
        this.formTemplateEl = this.shadowRootRef.getElementById('form-template') as HTMLTemplateElement;
        this.sectionTemplateEl = this.shadowRootRef.getElementById('section-template') as HTMLTemplateElement;
        this.shadowRootRef.getElementById('new-story')!.addEventListener('click', () => this.openForm(null));
        void this.loadData();
    }

    attributeChangedCallback(): void {
        if (!this.isConnected || !this.loadingEl) return;
        void this.loadData();
    }

    private async loadData(): Promise<void> {
        const projectId = this.getAttribute('project-id');
        if (projectId !== 'motivation' || !this.loadingEl) return;

        const currentLoad = ++this.loadSequence;
        this.loadingEl.hidden = false;
        this.errorEl.hidden = true;
        this.draftsEl.hidden = true;
        this.storiesEl.hidden = true;
        this.toolbarEl.hidden = true;

        try {
            const [{ stories }, { drafts }] = await Promise.all([
                ProjectsService.fetchMotivationStories(),
                ProjectsService.fetchStoryDrafts(),
            ]);
            if (currentLoad !== this.loadSequence || !this.isConnected || !this.loadingEl) return;
            this.render(stories, drafts);
        } catch (error) {
            this.log.error('Failed to load stories', error);
            if (currentLoad !== this.loadSequence || !this.isConnected || !this.loadingEl) return;
            this.loadingEl.hidden = true;
            this.errorEl.hidden = false;
            this.errorEl.textContent = error instanceof Error ? error.stack ?? error.message : String(error);
        }
    }

    private render(stories: ProjectStorySummary[], drafts: SavedStoryDraft[]): void {
        const onBoard = new Set(stories.map((story) => story.id));
        const waiting = drafts.filter((draft) => draft.status === 'open' || (draft.storyId !== null && !onBoard.has(draft.storyId)));
        this.draftsEl.replaceChildren(...waiting.map((draft) => this.buildDraftEntry(draft)));
        this.storiesEl.replaceChildren(...stories.map((story) => this.buildStoryEntry(story)));
        this.loadingEl.hidden = true;
        this.errorEl.hidden = true;
        this.toolbarEl.hidden = false;
        this.draftsEl.hidden = false;
        this.storiesEl.hidden = false;
    }

    private buildStoryEntry(story: ProjectStorySummary): DocumentFragment {
        const fragment = this.itemTemplateEl.content.cloneNode(true) as DocumentFragment;

        (fragment.querySelector('.item-id') as HTMLElement).textContent =
            story.storyPoints == null ? `Story ${story.id}` : `Story ${story.id} · ${story.storyPoints} pts`;

        const status = fragment.querySelector('.status') as HTMLElement;
        status.className = projectStatusClass(story.status);
        status.textContent = formatProjectStatusLabel(story.status);

        (fragment.querySelector('.item-title') as HTMLElement).textContent = story.title;
        if (story.status === 'in_progress') {
            (fragment.querySelector('.story-item') as HTMLDetailsElement).open = true;
        }

        const copy = fragment.querySelector('.item-copy') as HTMLElement;
        if (story.story) {
            copy.hidden = false;
            copy.textContent = story.story;
        }

        (fragment.querySelector('.item-meta') as HTMLElement).textContent =
            `${story.priority ?? 'No priority'} · ${story.path}`;
        return fragment;
    }

    private buildDraftEntry(draft: SavedStoryDraft): DocumentFragment {
        const fragment = this.draftTemplateEl.content.cloneNode(true) as DocumentFragment;
        const open = draft.status === 'open';
        (fragment.querySelector('.item-id') as HTMLElement).textContent = open ? 'Draft' : `Draft → story ${draft.storyId}`;
        (fragment.querySelector('.item-title') as HTMLElement).textContent = draft.title;
        (fragment.querySelector('.status') as HTMLElement).textContent = open ? 'Draft' : 'Imported';

        const copy = fragment.querySelector('.item-copy') as HTMLElement;
        if (draft.sections.story) {
            copy.hidden = false;
            copy.textContent = draft.sections.story;
        }
        (fragment.querySelector('.item-meta') as HTMLElement).textContent = open
            ? 'Waiting for the desktop import'
            : `Written as story ${draft.storyId}; it shows here once the repo is pulled`;

        const entry = fragment.querySelector('.draft-entry') as HTMLElement;
        if (open) {
            (fragment.querySelector('.draft-actions') as HTMLElement).hidden = false;
            fragment.querySelector('.edit-button')!.addEventListener('click', (ev) => {
                ev.preventDefault();
                this.openForm(draft, entry);
            });
            fragment.querySelector('.discard-button')!.addEventListener('click', (ev) => {
                ev.preventDefault();
                void this.discard(draft, entry);
            });
        }
        return fragment;
    }

    private async discard(draft: SavedStoryDraft, entry: HTMLElement): Promise<void> {
        if (!confirm(`Discard the draft "${draft.title}"?`)) return;
        const errorEl = entry.querySelector('.item-error') as HTMLElement;
        errorEl.hidden = true;
        try {
            await ProjectsService.discardStoryDraft(draft.id);
            await this.loadData();
        } catch (error) {
            this.log.error('Failed to discard the story draft', error);
            errorEl.hidden = false;
            errorEl.textContent = error instanceof Error ? error.stack ?? error.message : String(error);
        }
    }

    /** A new draft (`draft` null, the form above the drafts), or an open one edited in its place. */
    private openForm(draft: SavedStoryDraft | null, entry?: HTMLElement): void {
        const form = this.buildForm(draft, async (body) => {
            if (draft) await ProjectsService.updateStoryDraft(draft.id, body);
            else await ProjectsService.createStoryDraft(body);
            await this.loadData();
        });
        const li = document.createElement('li');
        li.className = 'story-entry story-entry--editing';
        li.appendChild(form);
        if (entry) entry.replaceWith(li);
        else this.draftsEl.prepend(li);
    }

    private buildForm(draft: SavedStoryDraft | null, onSubmit: (body: CreateStoryBody) => Promise<void>): HTMLElement {
        const fragment = this.formTemplateEl.content.cloneNode(true) as DocumentFragment;
        const form = fragment.querySelector('.story-form') as HTMLFormElement;
        const titleInput = form.querySelector('input[name=title]') as HTMLInputElement;
        const sectionsContainer = form.querySelector('.sections') as HTMLElement;
        const moreFields = form.querySelector('.more-fields') as HTMLDetailsElement;
        const moreContainer = form.querySelector('.more-sections') as HTMLElement;
        const errorEl = form.querySelector('.form-error') as HTMLElement;

        // A quick idea is a title and a line of story; the other sections wait under "More fields",
        // open from the start when an edited draft already uses one.
        titleInput.value = draft?.title ?? '';
        const textareas = new Map<StorySectionKey, HTMLTextAreaElement>();
        for (const key of STORY_SECTION_KEYS) {
            const sectionFragment = this.sectionTemplateEl.content.cloneNode(true) as DocumentFragment;
            (sectionFragment.querySelector('.field-label') as HTMLElement).textContent = STORY_SECTION_HEADINGS[key];
            const textarea = sectionFragment.querySelector('textarea') as HTMLTextAreaElement;
            textarea.value = draft?.sections[key] ?? '';
            textareas.set(key, textarea);
            if (key === 'story') {
                sectionsContainer.appendChild(sectionFragment);
            } else {
                textarea.rows = 2;
                if (textarea.value.trim()) moreFields.open = true;
                moreContainer.appendChild(sectionFragment);
            }
        }

        form.querySelector('.cancel-button')!.addEventListener('click', (ev) => {
            ev.preventDefault();
            void this.loadData();
        });

        form.addEventListener('submit', async (ev) => {
            ev.preventDefault();
            errorEl.hidden = true;
            const submit = form.querySelector('.save-button') as HTMLButtonElement;
            submit.disabled = true;
            try {
                // A blank section is left out: the draft (and later the file) has no empty headings.
                const sections: Partial<Record<StorySectionKey, string>> = {};
                for (const [key, ta] of textareas) {
                    if (ta.value.trim().length > 0) sections[key] = ta.value;
                }
                await onSubmit({ title: titleInput.value.trim(), sections });
            } catch (error) {
                this.log.error('Failed to save the story draft', error);
                errorEl.hidden = false;
                errorEl.textContent = error instanceof Error ? error.stack ?? error.message : String(error);
                submit.disabled = false;
            }
        });

        return form;
    }
}

if (!customElements.get('project-story-list')) {
    customElements.define('project-story-list', ProjectStoryList);
}
